"""Daily stats card (light + dark), generated by the refresh workflow. No third-party service.

    GH_TOKEN=... python scripts/stats.py [login]
"""
import json
import os
import sys
import urllib.request
from datetime import date

from theme import ADAPTIVE, adapt, esc, font_css, write

LOGIN = sys.argv[1] if len(sys.argv) > 1 else os.environ.get("GH_USER", "HridikH")
QUERY = """
query($login:String!){ user(login:$login){
  repositories(ownerAffiliations:OWNER, isFork:false, privacy:PUBLIC, first:100){
    totalCount nodes{ stargazerCount languages(first:10, orderBy:{field:SIZE,direction:DESC}){ edges{ size node{ name } } } } }
  contributionsCollection{ totalCommitContributions totalPullRequestContributions
    contributionCalendar{ totalContributions weeks{ contributionDays{ contributionCount } } } } } }"""


def fetch():
    req = urllib.request.Request(
        "https://api.github.com/graphql",
        data=json.dumps({"query": QUERY, "variables": {"login": LOGIN}}).encode(),
        headers={"Authorization": f"bearer {os.environ['GH_TOKEN']}", "Content-Type": "application/json"})
    data = json.load(urllib.request.urlopen(req))
    if "errors" in data:
        raise SystemExit(data["errors"])
    return data["data"]["user"]


def summarize(u):
    repos = u["repositories"]
    langs = {}
    for r in repos["nodes"]:
        for e in r["languages"]["edges"]:
            langs[e["node"]["name"]] = langs.get(e["node"]["name"], 0) + e["size"]
    total = sum(langs.values()) or 1
    top = sorted(langs.items(), key=lambda kv: -kv[1])[:5]
    cc = u["contributionsCollection"]
    weeks = [sum(d["contributionCount"] for d in w["contributionDays"]) for w in cc["contributionCalendar"]["weeks"]]
    return dict(
        contributions=cc["contributionCalendar"]["totalContributions"],
        commits=cc["totalCommitContributions"],
        prs=cc["totalPullRequestContributions"],
        repos=repos["totalCount"],
        stars=sum(r["stargazerCount"] for r in repos["nodes"]),
        langs=[(n, s / total) for n, s in top],
        weeks=weeks,
    )


W, H = 830, 200


def card(t, s):
    stats = [("contributions", s["contributions"]), ("commits", s["commits"]),
             ("public repos", s["repos"]), ("stars", s["stars"])]
    cells = ""
    for k, (label, v) in enumerate(stats):
        x = 28 + k * 112
        cells += (f'<text x="{x}" y="78" font-size="26" font-weight="700" fill="{t["text"]}">{v:,}</text>'
                  f'<text x="{x}" y="98" font-size="10.5" fill="{t["muted"]}" letter-spacing="1">{label.upper()}</text>')

    # Weekly contributions as a scope trace.
    sx, sy, sw, sh = 480, 26, 324, 96
    wk = s["weeks"][-52:] or [0]
    peak = max(wk) or 1
    pts = " ".join(f"{sx+10+(sw-20)*i/max(1,len(wk)-1):.1f},{sy+sh-12-(sh-42)*v/peak:.1f}" for i, v in enumerate(wk))
    scope = (f'<rect x="{sx}" y="{sy}" width="{sw}" height="{sh}" rx="8" fill="{t["bg"]}" stroke="{t["line"]}" stroke-width="1.2"/>'
             + "".join(f'<path d="M{sx+sw*k/6:.1f} {sy+6} V{sy+sh-6}" stroke="{t["grid"]}"/>' for k in range(1, 6)) +
             f'<polyline points="{pts}" fill="none" stroke="{t["accent"]}" stroke-width="2" stroke-linejoin="round"/>'
             f'<text x="{sx+10}" y="{sy+17}" font-size="10" fill="{t["accent"]}" letter-spacing="1">CH1</text>'
             f'<text x="{sx+sw-10}" y="{sy+17}" font-size="10" fill="{t["muted"]}" text-anchor="end">commits / week · 52 wk</text>')

    # Languages: one hue, stepped by opacity, so the palette stays single-accent.
    bar, x = "", 28.0
    legend = ""
    bw = W - 56
    for k, (name, frac) in enumerate(s["langs"]):
        op = 1 - k * 0.18
        w = bw * frac
        bar += f'<rect x="{x:.1f}" y="140" width="{max(w-2, 1):.1f}" height="10" rx="2" fill="{t["accent"]}" opacity="{op:.2f}"/>'
        legend += (f'<rect x="{28+k*156}" y="165" width="9" height="9" rx="2" fill="{t["accent"]}" opacity="{op:.2f}"/>'
                   f'<text x="{42+k*156}" y="173.5" font-size="11.5" fill="{t["text"]}">{esc(name)}'
                   f'<tspan fill="{t["muted"]}"> {frac*100:.0f}%</tspan></text>')
        x += w
    stamp = ""
    return (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}" width="{W}" height="{H}">'
            f'<title>GitHub activity, last 12 months</title><style>{font_css()}</style>'
            f'<rect x=".75" y=".75" width="{W-1.5}" height="{H-1.5}" rx="12" fill="{t["surface"]}" stroke="{t["line"]}" stroke-width="1.5"/>'
            f'<text x="28" y="38" font-size="10.5" fill="{t["muted"]}" letter-spacing="1.5">LAST 12 MONTHS · UPDATED {date.today():%Y-%m-%d}</text>'
            + cells + scope + f'<text x="28" y="128" font-size="10.5" fill="{t["muted"]}" letter-spacing="1.5">LANGUAGES</text>'
            + stamp + bar + legend + '</svg>')


if __name__ == "__main__":
    s = summarize(fetch())
    write("assets/live/stats.svg", adapt(card(ADAPTIVE, s)))
    print(json.dumps({k: v for k, v in s.items() if k != "weeks"}))
